// page.go — derived knowledge pages: standing answers to a fixed catalog
// of project questions, regenerated by the evolve sweep. Pages are engine
// state under pages/, outside format version 1: they cite facts and never
// outrank them as the recall surface.

package memory

import (
	"strings"
	"time"
)

// PageSpec is one catalog entry: the slug and the standing question.
type PageSpec struct {
	Name     string
	Question string
}

// pageCatalog fixes the questions a project's pages answer. The registry is
// closed, so the sweep cannot invent page topics and the injection budget
// stays deterministic. There is deliberately no initiatives entry: xi
// removed its goal feature, and pages must not reintroduce it.
var pageCatalog = []PageSpec{
	{"component-map", "How is this project's code organized, and what does each part own?"},
	{"core-concepts", "Which project-specific concepts must a reader know before changing code?"},
	{"conventions", "Which conventions does this project follow?"},
	{"key-decisions", "Which decisions shaped this project, and why were alternatives rejected?"},
	{"pitfalls", "Which known traps should a change avoid?"},
}

// PageCatalog returns the fixed page registry in canonical order.
func PageCatalog() []PageSpec {
	out := make([]PageSpec, len(pageCatalog))
	copy(out, pageCatalog)
	return out
}

// PageQuestion returns the standing question for a catalog slug.
func PageQuestion(name string) (string, bool) {
	for _, spec := range pageCatalog {
		if spec.Name == name {
			return spec.Question, true
		}
	}
	return "", false
}

// pageCatalogOrder ranks a slug inside the catalog; unknown names sink.
func pageCatalogOrder(name string) int {
	for i, spec := range pageCatalog {
		if spec.Name == name {
			return i
		}
	}
	return len(pageCatalog)
}

// maxPageSources caps a page's source list, matching the fact link cap.
const maxPageSources = 8

// maxPageBodyBytes clamps a page body at write. Pages are derived state, so
// unlike facts (ADR-005: no write is ever refused for size) the composition
// clamp is a write bound: a longer draft loses its tail, never a refusal.
const maxPageBodyBytes = 2 * 1024

// Page is one derived knowledge page.
type Page struct {
	Name     string   // catalog slug; the file's base name
	Question string   // the standing question the page answers
	Sources  []string // cited fact names; empty only for hand-written pages
	// SourceHashes holds one hash per source, in Sources order. It makes
	// staleness independent of filesystem timestamp resolution.
	SourceHashes []string
	UpdatedOn    string // YYYY-MM-DD stamp of the last regeneration
	Body         string
	// ModTime is the file's modification time; zero for pages not read from
	// disk. Staleness compares it against the cited facts' mtimes.
	ModTime time.Time
}

// ParsePage parses page-file content. Parsing is tolerant: a file without
// frontmatter takes its question from its first body line.
func splitPageHashes(raw string) []string {
	if strings.TrimSpace(raw) == "" {
		return nil
	}
	var hashes []string
	for _, item := range strings.Split(raw, ",") {
		hashes = append(hashes, strings.TrimSpace(item))
	}
	return hashes
}

func ParsePage(content string) Page {
	meta, body, ok := splitFrontmatter(NormalizeNewlines(strings.TrimPrefix(content, "\ufeff")))
	page := Page{Body: strings.Trim(body, "\n")}
	if !ok {
		page.Question = CollapseLine(firstNonEmptyLine(page.Body))
		return page
	}
	page.Name = strings.TrimSpace(meta["name"])
	page.Question = CollapseLine(meta["question"])
	page.Sources = normalizePageSources(strings.Split(meta["sources"], ","))
	page.SourceHashes = splitPageHashes(meta["sourceHashes"])
	page.UpdatedOn = strings.TrimSpace(meta["updatedOn"])
	return page
}

// FormatPage renders the canonical page file. An empty body emits the
// frontmatter block only.
func FormatPage(page Page) string {
	var b strings.Builder
	b.WriteString("---\n")
	b.WriteString("name: " + page.Name + "\n")
	b.WriteString("question: " + CollapseLine(page.Question) + "\n")
	if sources := normalizePageSources(page.Sources); len(sources) > 0 {
		b.WriteString("sources: " + strings.Join(sources, ", ") + "\n")
	}
	if len(page.SourceHashes) > 0 {
		b.WriteString("sourceHashes: " + strings.Join(page.SourceHashes, ", ") + "\n")
	}
	b.WriteString("updatedOn: " + strings.TrimSpace(page.UpdatedOn) + "\n")
	b.WriteString("---\n")
	if body := strings.Trim(page.Body, "\n"); body != "" {
		b.WriteString("\n" + body + "\n")
	}
	return b.String()
}

// preparePage normalizes a page for writing: the slug must name a catalog
// entry, an empty question takes the catalog question, and the body clamps.
func preparePage(page Page) (Page, error) {
	name := FactSlug(page.Name)
	question, ok := PageQuestion(name)
	if !ok {
		return Page{}, &Error{Code: CodeMissingField, Message: "unknown page name: " + page.Name}
	}
	page.Name = name
	if CollapseLine(page.Question) == "" {
		page.Question = question
	}
	page.Sources = normalizePageSources(page.Sources)
	page.UpdatedOn = strings.TrimSpace(page.UpdatedOn)
	page.Body = strings.Trim(page.Body, "\n")
	page.Body, _ = HeadBytes(page.Body, maxPageBodyBytes)
	return page, nil
}

// normalizePageSources slugs every entry and drops empty and duplicate
// names, so a page's sources stay valid fact addresses no matter what the
// model wrote.
func normalizePageSources(raw []string) []string {
	var sources []string
	seen := map[string]bool{}
	for _, entry := range raw {
		slug := FactSlug(entry)
		if slug == "" || seen[slug] {
			continue
		}
		seen[slug] = true
		sources = append(sources, slug)
		if len(sources) == maxPageSources {
			break
		}
	}
	return sources
}
